description:
Change under review: let users download the attachments they uploaded. The added file is shown in full.

`src/routes/attachments.ts` (added):
```ts
1 import { join, resolve } from "node:path";
2 import { requireSession } from "../auth/session.js";
3
4 const UPLOAD_ROOT = "/srv/app/uploads";
5
6 export const getAttachment = requireSession(async (req) => {
7   const name = new URL(req.url).searchParams.get("file");
8   if (name === null) return new Response("missing file", { status: 400 });
9   const userDir = join(UPLOAD_ROOT, String(req.session.userId));
10   const target = resolve(userDir, name);
11   if (!target.startsWith(userDir)) {
12     return new Response("forbidden", { status: 403 });
13   }
14   return new Response(Bun.file(target));
15 });
```

Each user's uploads are stored in `/srv/app/uploads/<userId>/`, where `userId` is the user's numeric id from the signed session cookie.
